+}
+
+@keyframes iso-typing {
+  0%, 100% { transform: translateY(0) rotate(0deg); }
+  20% { transform: translateY(-2px) rotate(-2deg); }
+  40% { transform: translateY(0) rotate(1deg); }
+  60% { transform: translateY(-2px) rotate(-1deg); }
+  80% { transform: translateY(0) rotate(2deg); }
+}
+
+@keyframes iso-idle {
+  0%, 85%, 100% { transform: translateY(0) rotate(0deg); }
+  88% { transform: translateY(-1px) rotate(1deg); }
+  91% { transform: translateY(0) rotate(-1deg); }
+  94% { transform: translateY(-1px) rotate(0deg); }
+}
+
+@keyframes iso-sway {
+  0%, 100% { transform: rotate(0deg) translateY(0); }
+  25% { transform: rotate(2deg) translateY(-1px); }
