+}
+
+@keyframes iso-walk {
+  0% { transform: translateX(-40px) translateY(20px); opacity: 0; }
+  20% { opacity: 1; }
+  100% { transform: translateX(0) translateY(0); opacity: 1; }
+}
+
+@keyframes iso-bounce {
+  0%, 100% { transform: translateY(0) scaleY(1); }
+  30% { transform: translateY(-4px) scaleY(1.04); }
+  50% { transform: translateY(0) scaleY(0.96); }
+  70% { transform: translateY(-2px) scaleY(1.02); }
+}
+
+@keyframes iso-stretch {
+  0%, 100% { transform: scaleY(1) translateY(0); }
+  30% { transform: scaleY(1.1) translateY(-3px); }
+  60% { transform: scaleY(0.95) translateY(0); }
+}
+
+@keyframes iso-shake {
+  0%, 100% { transform: translateX(0) rotate(0deg); }
+  15% { transform: translateX(-3px) rotate(-3deg); }
+  30% { transform: translateX(3px) rotate(3deg); }
+  45% { transform: translateX(-2px) rotate(-2deg); }
+  60% { transform: translateX(2px) rotate(2deg); }
+  75% { transform: translateX(-1px) rotate(0deg); }
+}
+
+@keyframes iso-steam {
+  0% { transform: translateY(0) scale(0.8); opacity: 0.6; }
+  50% { transform: translateY(-6px) scale(1.1); opacity: 0.3; }
+  100% { transform: translateY(-12px) scale(1.4); opacity: 0; }
+}
+
+@keyframes iso-blink {
+  0%, 42%, 44%, 100% { transform: scaleY(1); }
+  43% { transform: scaleY(0.1); }
+}
+
+@keyframes iso-look {
+  0%, 40%, 60%, 100% { transform: translateX(0); }
+  45% { transform: translateX(1px); }
+  55% { transform: translateX(-1px); }
+}
+
+@keyframes thought-pulse {
+  0%, 100% { opacity: 0.3; transform: scale(0.95); }
+  50% { opacity: 1; transform: scale(1.05); }
+}
+
+@keyframes iso-float {
+  0%, 100% { transform: translateY(0); }
+  50% { transform: translateY(-4px); }
+}
+
+@keyframes screen-flicker {
+  0%, 100% { opacity: 0.6; }
+  50% { opacity: 1; }
+}
+
+@keyframes iso-zzz {
+  0%, 100% { transform: translateY(0) translateX(0) scale(0.8); opacity: 0; }
+  20% { opacity: 0.8; }

